-- Run on a NEW empty petday database; do not overwrite existing data.
BEGIN;
CREATE TABLE users(id BIGSERIAL PRIMARY KEY, email TEXT NOT NULL UNIQUE, full_name TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'customer' CHECK (role IN ('customer','admin')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE pets(id BIGSERIAL PRIMARY KEY, owner_id BIGINT NOT NULL REFERENCES users(id), name TEXT NOT NULL, species TEXT NOT NULL CHECK(species IN ('Chó','Mèo')), breed TEXT NOT NULL DEFAULT '', age NUMERIC(5,1) NOT NULL CHECK(age>=0), weight NUMERIC(6,2) NOT NULL CHECK(weight>0 AND weight<=80), notes TEXT NOT NULL DEFAULT '', UNIQUE(id,owner_id));
CREATE TABLE bookings(id BIGSERIAL PRIMARY KEY, code TEXT NOT NULL UNIQUE, customer_id BIGINT NOT NULL REFERENCES users(id), pet_id BIGINT NOT NULL, service TEXT NOT NULL CHECK(service IN ('Grooming toàn diện','Spa dưỡng lông','Daycare cả ngày')), branch TEXT NOT NULL CHECK(branch IN ('PetDay Thảo Điền','PetDay Phú Mỹ Hưng')), booking_date DATE NOT NULL, slot TEXT NOT NULL CHECK(slot IN ('08:30','10:00','13:30','15:00','17:30')), status TEXT NOT NULL DEFAULT 'Đang chờ xác nhận' CHECK(status IN ('Đang chờ xác nhận','Đã xác nhận','Đang thực hiện','Hoàn tất','Đã hủy')), payment_status TEXT NOT NULL DEFAULT 'Chưa thanh toán' CHECK(payment_status IN ('Chưa thanh toán','Thanh toán mô phỏng thành công','Thanh toán thất bại (mô phỏng)','Đã hoàn tiền (mô phỏng)')), line_items JSONB NOT NULL, total BIGINT NOT NULL CHECK(total>=0), idempotency_key TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), FOREIGN KEY(pet_id,customer_id) REFERENCES pets(id,owner_id), UNIQUE(customer_id,idempotency_key));
CREATE INDEX booking_capacity_idx ON bookings(branch,booking_date,slot,status);
CREATE TABLE care_records(booking_id BIGINT PRIMARY KEY REFERENCES bookings(id), notes TEXT NOT NULL CHECK(length(trim(notes))>0), care_date DATE NOT NULL);
CREATE TABLE reviews(booking_id BIGINT PRIMARY KEY REFERENCES bookings(id), customer_id BIGINT NOT NULL REFERENCES users(id), rating INT NOT NULL CHECK(rating BETWEEN 1 AND 5), comment TEXT NOT NULL CHECK(length(trim(comment))>0), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
COMMIT;
